let calendarDate=new Date(2026,9,26),calendarView='week';
async function schedule(){const d=await api('schedule');d.appointments=d.appointments.filter(a=>(schedFilter.type==='all'||a.entity_type===schedFilter.type)&&(schedFilter.status==='all'||a.status===schedFilter.status)&&(schedFilter.team==='all'||JSON.parse(a.assigned_user_ids_json||'[]').includes(Number(schedFilter.team))));const start=new Date(calendarDate);if(calendarView!=='day')start.setDate(start.getDate()-start.getDay());const days=Array.from({length:calendarView==='day'?1:7},(_,i)=>{const day=new Date(start);day.setDate(day.getDate()+i);return day;});const localDate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const cell=(day,h)=>{const date=localDate(day);return `<div class="${h===8||h>=17||[0,6].includes(day.getDay())?'nonbusiness':''}" data-slot="${date}T${String(h).padStart(2,'0')}:00">${d.appointments.filter(a=>{const local=new Date(a.start_at);return localDate(local)===date&&(calendarView==='month'||local.getHours()===h);}).map(a=>`<button class="appointment" draggable="${a.entity_type==='visit'}" data-visit-drag="${a.entity_id}" data-appointment="${a.entity_type}:${a.entity_id}">${esc(a.title)}<br>${new Date(a.start_at).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}</button>`).join('')}</div>`;};const grid=calendarView==='month'?`<div class="calendar" style="grid-template-columns:repeat(7,1fr)">${Array.from({length:35},(_,i)=>{const day=new Date(calendarDate.getFullYear(),calendarDate.getMonth(),1);day.setDate(1-day.getDay()+i);return `<section style="min-height:100px;padding:8px;border:1px solid #dadfe2">${day.getDate()}${cell(day,9)}</section>`;}).join('')}</div>`:`<div class="calendar" style="grid-template-columns:60px repeat(${days.length},minmax(90px,1fr))"><div></div>${days.map(day=>`<div class="day ${localDate(day)===localDate(calendarDate)?'today':''}">${day.getDate()} ${day.toLocaleDateString('en-US',{weekday:'short'})}</div>`).join('')}<div>↓ Anytime</div>${'<div></div>'.repeat(days.length)}${Array.from({length:11},(_,i)=>`<div>${(i+8)%12||12} ${i+8>=12?'PM':'AM'}</div>${days.map(day=>cell(day,i+8)).join('')}`).join('')}</div>`;return `<div class="schedule-toolbar"><button class="month-title" data-action="calendar-date">${calendarDate.toLocaleDateString('en-US',{month:'long',year:'numeric'})} ⌄</button>${btn('←','prev-week')}${btn('→','next-week')}${btn('Today','schedule')}${btn('Find a Time','find-time',true)}${['type','team','status'].map(k=>`<button class="pill" data-action="sched-${k}">${title(k)} | ${esc(k==='team'&&schedFilter[k]!=='all'?team.find(u=>u.id===Number(schedFilter[k]))?.name||'Unknown':title(schedFilter[k]))}</button>`).join('')}<div class="views"><button data-calendar-view="month">Month</button><button class="active" data-calendar-view="week">Week</button><button data-calendar-view="day">Day</button></div>${btn('↧ '+d.unscheduled.length,'unscheduled')}${btn('Map','schedule-map')}${btn('⋯ More','schedule-more')}</div>${grid}`;}
let timesheetTab='Timesheets',timeDate=new Date(2026,9,26),timeView='Day';
async function timesheets(){const all=await api('time-entries'),prefs=await api('preferences'),end=new Date(timeDate);end.setDate(end.getDate()+(timeView==='Week'?7:1));const entries=all.filter(e=>Date.parse(e.start_at)>=+timeDate&&Date.parse(e.start_at)<+end),active=all.find(e=>e.user_id===user.id&&!e.end_at),duration=n=>Math.floor(n/60)+':'+String(Math.round(n%60)).padStart(2,'0'),minutes=id=>entries.filter(e=>e.user_id===id).reduce((s,e)=>s+e.duration_minutes,0),key=timeDate.toLocaleDateString('en-CA'),saved=name=>prefs.some(p=>p.name===name&&JSON.parse(p.value_json).enabled),last=new Date(+end-86400000),dateLabel=timeView==='Week'?`${timeDate.toLocaleDateString('en-US',{month:'short',day:'numeric'})} - ${last.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}`:timeDate.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});return head('Timesheets',btn('Settings','settings/work-settings'))+`<section class="card timesheet-banner"><div><h2>Spend less time fixing crew timesheets</h2><p>Crew leads clock the team in and out from mobile, so every team member's time is captured when work starts and stops</p>${btn('Learn more','settings/work-settings')}</div><img class="timesheet-art" src="/assets/timesheets_banner_art.jpg" alt="Mobile crew time tracking — Timer started"></section><div class="tabs">${['Timesheets','Approve timesheets','Confirm payroll'].map(n=>`<button class="${timesheetTab===n?'active':''}" data-timesheet-tab="${n}">${n}</button>`).join('')}</div><div class="time-navigation"><button data-time-nav="-1" aria-label="Previous period">‹</button><button>${timeView==='Day'?timeDate.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'}):dateLabel}</button><button data-time-nav="1" aria-label="Next period">→</button><button data-time-nav="today">Today</button><div class="views">${['Day','Week'].map(n=>`<button class="${timeView===n?'active':''}" data-time-view="${n}">${n}</button>`).join('')}</div><span class="time-spacer"></span>${btn('+ Expand all','expand')}<select id="time-team-filter" aria-label="Team"><option value="">Team | All</option>${team.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></div><div class="timer-layout"><div>${timesheetTab==='Timesheets'?team.map(t=>`<details class="accordion" data-time-user="${t.id}"><summary><span class="avatar">${esc(t.name.split(' ').map(n=>n[0]).join(''))}</span>${esc(t.name)}<strong>${duration(minutes(t.id))}</strong></summary><div class="actions">${btn('+ Add Time','add-time:'+t.id)}${t.id===user.id?btn(active?'Clock Out':'Clock In',active?'clock-out:'+active.id:'clock-in:'+user.id):''}</div>${entries.filter(e=>e.user_id===t.id).map(e=>`<p>${esc(e.start_at)} — ${esc(e.end_at||'Timer running')} · ${duration(e.duration_minutes)}</p>`).join('')||'<p class="muted">No time logged in this period</p>'}</details>`).join(''):timesheetTab==='Approve timesheets'?`<section class="card"><h2>Review team hours</h2>${team.map(t=>`<label class="toggle-row"><span>${esc(t.name)} · ${duration(minutes(t.id))}<small>Approve the hours for this period</small></span><input type="checkbox" data-preference="time-approved-${key}-${t.id}" ${saved('time-approved-'+key+'-'+t.id)?'checked':''}></label>`).join('')}</section>`:`<section class="card"><h2>Confirm payroll</h2>${table(team,[['Employee',t=>esc(t.name)],['Hours',t=>duration(minutes(t.id))],['Approval',t=>saved('time-approved-'+key+'-'+t.id)?'Approved':'Needs approval']])}<label class="toggle-row">Payroll confirmed for this period<input type="checkbox" data-preference="payroll-${key}" ${saved('payroll-'+key)?'checked':''}></label>${btn('Export payroll CSV','export-payroll')}</section>`}<p class="muted">Showing 1-${team.length} of ${team.length}</p></div></div>`;}
async function pipeline(){const d=await api('pipeline');return head('Pipeline',btn('New Request','new-request',true))+`<div class="kanban">${Object.entries(d).map(([stage,items])=>`<section class="lane" data-stage="${esc(stage)}"><h3>${esc(stage)} <small>${items.length}</small></h3>${items.map(x=>`<div class="card" draggable="true" data-resource="${x.resource}" data-id="${x.id}"><strong>${esc(x.title||x.subject||x.display_name)}</strong><p>${esc(clientName(x.client_id))}</p>${money(x.total_cents)}</div>`).join('')}</section>`).join('')}</div>`;}
async function bookkeeping(){const d=await api('bookkeeping');return head('Bookkeeping',btn('Sync QuickBooks Online','sync',true))+`<div class="stats">${[['Income',d.income_cents],['Expenses',d.expense_cents],['Net income',d.income_cents-d.expense_cents],['Tax',d.tax_cents]].map(([n,v])=>`<div class="card"><h3>${n}</h3><div class="number">${money(v)}</div></div>`).join('')}</div><p>QuickBooks Online · ${esc(d.integration?.status)} · Last sync ${esc(d.integration?.last_sync_at||'Not yet synced')}</p><h2>Reconciliation</h2>${table(d.ledger,[['Date',x=>esc(x.date?.slice(0,10))],['Name',x=>esc(x.name)],['Type',x=>esc(x.type)],['Category',x=>x.type==='expense'?`<button data-categorize="${x.id}">${esc(x.category)}</button>`:esc(x.category)],['Amount',x=>money(x.amount_cents)]])}`;}
const reportGroups={'Jobber Payments':['Transactions','Legacy Reports ⌄'],'Financial reports':['Projected income','Transaction list','Invoices','Taxation','Aged receivables','Bad debt','Client balance summary'],'Work reports':['Visits','One-off jobs','Recurring jobs','Requests','Checklists','Quotes','Team productivity','Salesperson performance','Products & Services','Waypoints'],'Client reports':['Clients','Lead source','Client communications','Job follow-up emails','Client contact info','Property list','Client re-engagement'],'Expense reports':['Expenses','Timesheets','Mileage'],'Account reports':['Delete log']};
const reportTypes={'Clients':'clients','Lead source':'clients','Legacy Reports ⌄':'payments','Invoices':'invoices','Payouts':'payments','Client balance summary':'clients','Visits':'visits','One-off jobs':'jobs','Recurring jobs':'jobs','Requests':'requests','Checklists':'checklists','Quotes':'quotes','Team productivity':'team_productivity','Salesperson performance':'quote_conversion','Transactions':'payments','Projected income':'invoices','Transaction list':'payments','Taxation':'invoices','Aged receivables':'aging_receivables','Bad debt':'invoices','Products & Services':'catalog','Waypoints':'schedule','Timesheets':'time_tracking','Expenses':'expenses','Mileage':'expenses','Client communications':'messages','Job follow-up emails':'messages','Client contact info':'clients','Property list':'properties','Client re-engagement':'clients','Delete log':'client_activity'};
function reports(){const order=[['Jobber Payments','Financial reports'],['Work reports'],['Client reports','Expense reports','Account reports']];return head(route==='custom-reports'?'Custom Reports':'Reports')+`<div class="reports">${order.map(column=>`<div class="report-column">${column.map(name=>`<section class="card">${''}<h2>${name}</h2>${reportGroups[name].map(n=>`<a class="report-link" data-go="report/${encodeURIComponent(n)}">${n}${['Client balance summary','Lead source'].includes(n)?' <span class="new-report">NEW</span>':''}<small>${esc(({ 'Projected income':'Track expected income from your outstanding invoices','Aged receivables':'See which clients have overdue balances','Timesheets':'Review employee hours and time entries','Client contact info':'View contact details for all your clients','Property list':'Review service addresses and property details','Expenses':'Track your job costs and logged expenses'})[n]||'View and export '+n.toLowerCase()+' for your business')}</small></a>`).join('')}</section>`).join('')}</div>`).join('')}</div>`;}
async function reportPage(name,version=viewVersion){name=decodeURIComponent(name);const type=reportTypes[name]||'revenue',direct=['catalog','schedule','expenses','messages','clients','properties','visits','jobs','requests','checklists','quotes'].includes(type);const fetched=await api(direct?type:'reports/'+type);if(version!==viewVersion)return '';resource='';let list=Array.isArray(fetched)?fetched:fetched.appointments||[];if(name==='One-off jobs'||name==='Recurring jobs')list=list.filter(x=>x.job_type===(name==='One-off jobs'?'one_off':'recurring'));if(name==='Bad debt')list=list.filter(x=>x.status==='bad_debt');if(name==='Projected income')list=list.filter(x=>x.balance_due_cents>0&&!['void','bad_debt','draft'].includes(x.status));if(name==='Client balance summary')list=list.map(x=>({id:x.id,client:x.display_name,balance_cents:x.balance_cents}));if(name==='Taxation')list=list.map(x=>({id:x.id,invoice:x.invoice_number,status:x.status,created_at:x.created_at,subtotal_cents:x.subtotal_cents,tax_cents:x.tax_cents,total_cents:x.total_cents}));rows=list;return head(name,btn('Export CSV','export-report'))+`<div class="filters"><label>From<input type="date" id="report-from"></label><label>To<input type="date" id="report-to"></label>${btn('Apply','filter-report')}</div><div class="card"><h3>${list.length} records</h3><p>Total ${money(total(list))}</p></div><div id="report-table">${genericTable(list)}</div>`;}
function genericTable(list){const keys=Object.keys(list[0]||{}).filter(k=>!k.endsWith('_json')&&!['organization_id','password_hash','portal_token'].includes(k)).slice(0,7);return table(list,keys.map(k=>[title(k),x=>esc(k.endsWith('_cents')?money(x[k]):x[k])]));}
async function collection(type,name,version=viewVersion){const fetched=await api(type);if(version!==viewVersion)return '';resource=type;rows=fetched;return head(name,btn('New '+name,'generic-new',true))+genericTable(rows);}
