function bindCampaigns(){if(!$('#campaign-search'))return;const apply=()=>{const q=$('#campaign-search').value.toLowerCase(),status=$('#campaign-status-filter').value,creator=$('#campaign-creator-filter').value,type=$('#campaign-type-filter').value;const filtered=campaignRows.filter(c=>(!status||c.status===status)&&(!creator||(c.created_by||'Jack Surwald')===creator)&&(!type||campaignType(c)===type)&&`${c.name} ${c.subject}`.toLowerCase().includes(q));$('#campaign-table').innerHTML=table(sortCampaignList(filtered),campaignColumns);$('#campaign-count').textContent=`(${filtered.length} results)`;bindSort();};const bindSort=()=>document.querySelectorAll('#campaign-table th').forEach((th,i)=>{const key=['name','opened_count','clicked_count','jobs_count','status',null,null,'created_at'][i];if(!key)return;th.tabIndex=0;th.setAttribute('aria-sort',campaignSort.key===key?(campaignSort.direction===1?'ascending':'descending'):'none');const sort=()=>{campaignSort={key,direction:campaignSort.key===key?-campaignSort.direction:1};apply();};th.onclick=sort;th.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();sort();}};});$('#campaign-search').oninput=apply;for(const id of ['creator','status','type'])$('#campaign-'+id+'-filter').onchange=apply;bindSort();}
